/// Builds the resource portability descriptor served through
/// `resource_support_fn` (heap-backed, so it lives behind the `LazyLock`
/// rather than in the `ProviderInfo` static).
fn build_resource_support() -> ProviderCapabilities {
    ProviderCapabilities {
        provider: Provider::Gemini,
        skills: ResourceSupport {
            level: SupportLevel::Full,
            format: Some(ResourceFormat::Markdown),
            repo_path: Some(PathBuf::from(".gemini/skills")),
            user_path: Some(PathBuf::from(".gemini/skills")),
            also_reads_from: vec![],
            notes: Some("Also supports .gemini/modules/ as context modules"),
            properties: Some(ResourcePropertySchema::new(
                &["name", "description"],
                &[],
                "claudine/docs/cross-referencing/gemini-cli.md",
            )),
        },
        commands: ResourceSupport {
            level: SupportLevel::CustomFormat,
            format: Some(ResourceFormat::Toml),
            repo_path: Some(PathBuf::from(".gemini/commands")),
            user_path: Some(PathBuf::from(".gemini/commands")),
            also_reads_from: vec![],
            notes: Some("Uses TOML format with {{args}} placeholder"),
            properties: Some(ResourcePropertySchema::new(
                &["prompt"],
                &["description"],
                "claudine/docs/cross-referencing/gemini-cli.md",
            )),
        },
        agents: ResourceSupport {
            level: SupportLevel::CustomFormat,
            format: Some(ResourceFormat::Markdown),
            repo_path: Some(PathBuf::from(".gemini/agents")),
            user_path: Some(PathBuf::from(".gemini/agents")),
            also_reads_from: vec![],
            notes: Some("Sub-agent markdown definitions are experimental"),
            properties: Some(ResourcePropertySchema::new(
                &["name", "description"],
                &["kind", "tools", "model", "temperature", "max_turns", "timeout_mins"],
                "claudine/docs/cross-referencing/gemini-cli.md",
            )),
        },
        scripts: ResourceSupport {
            level: SupportLevel::None,
            format: None,
            repo_path: None,
            user_path: None,
            also_reads_from: vec![],
            notes: Some("Scripts stored within skill directories"),
            properties: None,
        },
        skill_frontmatter: SkillFrontmatter {
            name: true,
            description: true,
            license: false,
            compatibility: false,
            metadata: false,
            allowed_tools: false,
            user_invocable: false,
            disable_model_invocation: false,
        },
    }
}
